// Authentic wallet code cells for the four wallet versions the TON proof
// verifier accepts, captured from the canonical @ton/ton package (16.3.0, MIT)
// on 2026-09-20 and cross-checked against mainnet: a sample of 30 active
// wallets taken chain-wide resolved to exactly these code hashes under the
// labels toncenter reports (wallet_v5r1, wallet_v4r2, wallet_v3r2).
//
// The verifier never needs a local copy of the code at runtime, because the
// wallet supplies its own stateInit and we only hash it. These cells exist so
// tests can assemble a stateInit around a throwaway keypair: a real wallet's
// stateInit carries a public key whose secret we do not have, so it cannot be
// used to produce a signature.
export const WALLET_CODE_BOC = {
  v3r1: "te6cckEBAQEAYgAAwP8AIN0gggFMl7qXMO1E0NcLH+Ck8mCDCNcYINMf0x/TH/gjE7vyY+1E0NMf0x/T/9FRMrryoVFEuvKiBPkBVBBV+RDyo/gAkyDXSpbTB9QC+wDo0QGkyMsfyx/L/8ntVD++buA=",
  v3r2: "te6cckEBAQEAcQAA3v8AIN0gggFMl7ohggEznLqxn3Gw7UTQ0x/THzHXC//jBOCk8mCDCNcYINMf0x/TH/gjE7vyY+1E0NMf0x/T/9FRMrryoVFEuvKiBPkBVBBV+RDyo/gAkyDXSpbTB9QC+wDo0QGkyMsfyx/L/8ntVBC9ba0=",
  v4r2: "",
  w5r1: "",
} as const;

